# integration_fims_bayesian_prior_predictive ----
## Setup ----
testthat::skip_if(
  Sys.getenv("RUN_SLOW_TESTS") != "true",
  "Skipping: RUN_SLOW_TESTS is not set to true."
)

load(testthat::test_path("fixtures", "integration_test_data.RData"))
data("data_big")

# Set the iteration ID to 1 for accessing specific input list
iter_id <- 1

# Extract model input data for the specified iteration
om_input <- om_input_list[[iter_id]]

## IO correctness ----
test_that("posterior equals prior with no data", {
  # This test sets up a model without data likelihood components. All
  # parameters without priors are fixed. Only selectivity parameters are
  # estimated and given priors, with the same mean and sd for the fishery and
  # survey fleets. With no data the posterior is the prior, so the posterior
  # mode of each selectivity parameter should be its prior mean and its
  # standard error should be its prior sd. The test checks the mode and
  # standard error from fit_fims() and, when SparseNUTS is installed, from
  # SparseNUTS.

  # Every observation is -999, which drops its log density, so the data add
  # nothing to the objective.
  data_types <- c("catch", "index", "age_comp", "length_comp")
  data_4_model <- data_big |>
    dplyr::mutate(
      observed = dplyr::if_else(type %in% data_types, -999, observed)
    ) |>
    FIMSFrame()

  selectivity_input <- tibble::tibble(
    module_name = "Selectivity",
    fleet = c("fleet1", "fleet1", "survey1", "survey1"),
    label = c("inflection_point", "slope", "inflection_point", "slope"),
    value = c(
      om_input[["sel_fleet"]][["fleet1"]][["A50.sel1"]],
      om_input[["sel_fleet"]][["fleet1"]][["slope.sel1"]],
      om_input[["sel_survey"]][["survey1"]][["A50.sel1"]],
      om_input[["sel_survey"]][["survey1"]][["slope.sel1"]]
    )
  )
  # Every value but the 4 selectivity parameters is held constant. The
  # recruitment deviations have no process distribution, because a process
  # needs an estimated value to score.
  parameters <- setup_default_parameters(data = data_4_model) |>
    dplyr::rows_update(
      selectivity_input,
      by = c("module_name", "fleet", "label")
    ) |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        module_name == "Selectivity", "fixed_effects", "constant"
      ),
      distribution_type = dplyr::if_else(
        module_name == "Recruitment", NA_character_, distribution_type
      ),
      distribution = dplyr::if_else(
        module_name == "Recruitment", NA_character_, distribution
      )
    )

  # Set up priors for selectivity parameters. add_priors() takes 1 fleet per
  # call, so the fishery and survey each get a prior with the same mean and sd.
  slope_input <- dplyr::filter(selectivity_input, label == "slope")[["value"]]
  slope_mean <- mean(slope_input)
  slope_sd <- 3
  inflection_point_input <- dplyr::filter(
    selectivity_input, label == "inflection_point"
  )[["value"]]
  inflection_point_mean <- mean(inflection_point_input)
  inflection_point_sd <- 3
  parameters <- parameters |>
    add_priors(
      slope ~ normal(mean = slope_mean, sd = slope_sd),
      module_name = "Selectivity",
      fleet = "fleet1"
    ) |>
    add_priors(
      slope ~ normal(mean = slope_mean, sd = slope_sd),
      module_name = "Selectivity",
      fleet = "survey1"
    ) |>
    add_priors(
      inflection_point ~ normal(
        mean = inflection_point_mean, sd = inflection_point_sd
      ),
      module_name = "Selectivity",
      fleet = "fleet1"
    ) |>
    add_priors(
      inflection_point ~ normal(
        mean = inflection_point_mean, sd = inflection_point_sd
      ),
      module_name = "Selectivity",
      fleet = "survey1"
    )

  fit <- parameters |>
    initialize_fims(data = data_4_model) |>
    fit_fims(optimize = FALSE)
  obj <- get_obj(fit)

  #' @description Test that the number of parameters in the model matches the expected number of parameters (4 selectivity parameters).
  expect_equal(
    object = length(obj[["par"]]) + length(obj[["env"]][["random"]]),
    expected = 4
  )

  # Test the prior nll values
  report <- get_report(fit)
  report_nll <- stats::setNames(
    report[["nll_components"]],
    FIMS:::label_nll_components(get_input(fit)[["model_data"]])
  )
  slope_nll <- report_nll[
    c("Selectivity.fleet1.slope", "Selectivity.survey1.slope")
  ]
  inflection_point_nll <- report_nll[
    c(
      "Selectivity.fleet1.inflection_point",
      "Selectivity.survey1.inflection_point"
    )
  ]
  #' @description Test that the fishery and survey slope prior nll values sum to the normal negative log density of the slope inputs.
  expect_equal(
    object = sum(slope_nll),
    expected = -sum(stats::dnorm(
      slope_input,
      mean = slope_mean, sd = slope_sd, log = TRUE
    ))
  )
  #' @description Test that the fishery and survey inflection point prior nll values sum to the normal negative log density of the inflection point inputs.
  expect_equal(
    object = sum(inflection_point_nll),
    expected = -sum(stats::dnorm(
      inflection_point_input,
      mean = inflection_point_mean, sd = inflection_point_sd, log = TRUE
    ))
  )
  #' @description Test that the data add nothing to the objective, so it is the sum of the 4 prior nll values.
  expect_equal(
    object = report[["jnll"]],
    expected = sum(slope_nll) + sum(inflection_point_nll)
  )

  # The posterior mode and its standard error from the Hessian are what
  # SparseNUTS reports as `mle` below. fit_fims() finds them without
  # SparseNUTS.
  mode_estimates <- parameters |>
    initialize_fims(data = data_4_model) |>
    fit_fims(optimize = TRUE) |>
    get_estimates() |>
    dplyr::filter(
      module_name == "Selectivity",
      label %in% c("inflection_point", "slope")
    )
  inflection_point_mode <- dplyr::filter(
    mode_estimates, label == "inflection_point"
  )
  slope_mode <- dplyr::filter(mode_estimates, label == "slope")
  #' @description Test that the posterior modes from fit_fims() for inflection point match the prior means.
  expect_equal(
    object = inflection_point_mode[["estimated"]],
    expected = rep(inflection_point_mean, 2)
  )
  #' @description Test that the posterior modes from fit_fims() for slope match the prior means.
  expect_equal(
    object = slope_mode[["estimated"]],
    expected = rep(slope_mean, 2)
  )
  #' @description Test that the standard errors from fit_fims() for inflection point match the prior standard deviations.
  expect_equal(
    object = inflection_point_mode[["uncertainty"]],
    expected = rep(inflection_point_sd, 2)
  )
  #' @description Test that the standard errors from fit_fims() for slope match the prior standard deviations.
  expect_equal(
    object = slope_mode[["uncertainty"]],
    expected = rep(slope_sd, 2)
  )

  # Fit MCMC using SparseNUTS
  testthat::skip_if_not_installed("SparseNUTS")
  mcmc_fit <- NULL
  invisible(capture.output(
    invisible(capture.output(
      mcmc_fit <- SparseNUTS::sample_snuts(
        obj,
        chains = 1,
        print = FALSE,
        refresh = 0,
        quiet = TRUE
      ),
      type = "message"
    ))
  ))
  # The mle values are in the order of the estimated parameters.
  inflection_point_position <- grep("inflection_point", names(obj[["par"]]))
  slope_position <- grep("slope", names(obj[["par"]]))
  inflection_point_est <- mcmc_fit[["mle"]][["est"]][inflection_point_position]
  inflection_point_se <- mcmc_fit[["mle"]][["se"]][inflection_point_position]
  slope_est <- mcmc_fit[["mle"]][["est"]][slope_position]
  slope_se <- mcmc_fit[["mle"]][["se"]][slope_position]
  for (i in 1:2) {
    #' @description Test that the posterior modes from SparseNUTS for inflection point match the prior means.
    expect_equal(inflection_point_est[[i]], inflection_point_mean)
    #' @description Test that the posterior modes from SparseNUTS for slope match the prior means.
    expect_equal(slope_est[[i]], slope_mean)
    #' @description Test that the standard errors from SparseNUTS for inflection point match the prior standard deviations.
    expect_equal(inflection_point_se[[i]], inflection_point_sd)
    #' @description Test that the standard errors from SparseNUTS for slope match the prior standard deviations.
    expect_equal(slope_se[[i]], slope_sd)
  }
})

